{"code":"import pandas as pd
import json

# Setup the environment to test the code
# Get the data first
df_orders = pd.read_sql_query("SELECT * FROM orders", conn)
dfs = [df_orders]

# --- BEGIN CODE ---
def processing(dfs):
    # Load the orders DataFrame
    df = dfs[0].copy()

    # Parse the 'details' column (assuming it's a stringified JSON)
    # The example data shows the 'details' column is a stringified JSON.
    # IMPORTANT: Need to account for potential errors in JSON parsing, 
    # but the tool's python_interpreter can just use literal_eval if json.loads fails, 
    # or just assume valid JSON based on the example. The example used json.loads.
    import ast
    def parse_json(x):
        try:
            return json.loads(x.replace("'", "\"")) # json.loads often fails with single quotes
        except:
            try:
                return ast.literal_eval(x)
            except:
                return None

    df['details_parsed'] = df['details'].apply(parse_json)

    def get_coupon(x):
        if isinstance(x, dict):
            return x.get('coupon')
        return None                

    df['coupon'] = df['details_parsed'].apply(get_coupon)

    coupon_order_count = df['coupon'].notnull().sum()

    return pd.DataFrame({'coupon_order_count': [coupon_order_count]})

# Run it
program_output = processing(dfs)
print(program_output)
"}

